weights = [0.02, -0.05, 0.04, 0.01, 8.0, -0.03, 0.06, -0.02]    # one outlier: 8.0

def mean_error(values, group_size):
    errors = []
    for start in range(0, len(values), group_size):
        group = values[start:start + group_size]
        scale = max(abs(v) for v in group) / 127
        errors += [abs(round(v / scale) * scale - v) for v in group]
    return round(sum(errors) / len(errors), 5)

results = {}
for size in [8, 4, 2]:
    results[size] = mean_error(weights, size)

for size, err in results.items():
    print(f"group size {size}: mean error {err}")
